from decimal import Decimal

import pytest
from hypothesis import given
from hypothesis import strategies as st

from refproj.pricing import MAX_PRICE, format_price, parse_price


@st.composite
def prices(draw: st.DrawFn) -> Decimal:
    """Every price from 0.00 to 9,999,999.99 in whole cents, with or without trailing zeros."""
    cents = draw(st.integers(min_value=0, max_value=999_999_999))
    price = Decimal(cents).scaleb(-2)
    return price.normalize() if draw(st.booleans()) else price


def test_format_always_prints_two_decimals() -> None:
    assert format_price(Decimal("12.5")) == "12.50"


def test_format_groups_thousands_by_commas() -> None:
    assert format_price(Decimal("1234.5")) == "1,234.50"


def test_format_of_zero_is_zero_point_zero_zero() -> None:
    assert format_price(Decimal("0")) == "0.00"


def test_format_of_the_highest_price_groups_every_thousand() -> None:
    assert MAX_PRICE == Decimal("9999999.99")
    assert format_price(MAX_PRICE) == "9,999,999.99"


def test_format_rejects_a_price_above_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("10000000.00"))


def test_format_rejects_a_price_below_the_range() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("-0.01"))


def test_format_rejects_a_fraction_of_a_cent_instead_of_rounding() -> None:
    with pytest.raises(ValueError, match="not a price"):
        format_price(Decimal("12.345"))


def test_parse_reads_a_printed_price_with_commas_in_cents() -> None:
    assert str(parse_price("1,234.50")) == "1234.50"


def test_parse_reads_a_price_with_the_commas_left_out_in_cents() -> None:
    assert str(parse_price("1234.50")) == "1234.50"


def test_parse_reads_the_lowest_and_the_highest_printed_price_in_cents() -> None:
    assert str(parse_price("0.00")) == "0.00"
    assert str(parse_price("9,999,999.99")) == "9999999.99"


@pytest.mark.parametrize("text", ["12.5", "12", "1,23.00", "", "abc"])
def test_parse_rejects_text_that_is_not_a_printed_price(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["$12.50", "12,50", "1 234.50"])
def test_parse_rejects_a_currency_sign_and_other_separators(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@pytest.mark.parametrize("text", ["10,000,000.00", "10000000.00", "-1.00"])
def test_parse_rejects_text_that_stands_for_no_price_in_the_range(text: str) -> None:
    with pytest.raises(ValueError, match="not a price"):
        parse_price(text)


@given(prices())
def test_I1_a_printed_price_reads_back_as_the_same_price(price: Decimal) -> None:
